import{_ as i,o as t,c as a,a0 as o}from"./chunks/framework.C0WKPwzJ.js";const u=JSON.parse('{"title":"Initial setup","description":"Install the plugin, sign in, connect the GitHub App, and run doctor.","frontmatter":{"title":"Initial setup","description":"Install the plugin, sign in, connect the GitHub App, and run doctor."},"headers":[],"relativePath":"workflows/initial-setup.md","filePath":"workflows/initial-setup.md","lastUpdated":1788171427000}'),n={name:"workflows/initial-setup.md"};function s(l,e,p,r,d,c){return t(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="initial-setup" tabindex="-1">Initial setup <a class="header-anchor" href="#initial-setup" aria-label="Permalink to &quot;Initial setup&quot;">​</a></h1><p>First day on a repository, or mail / board commands started failing.</p><ol><li>Install the plugin (<a href="./../install">Install</a>): <code>pnpm autodevelop:import --apply</code>, then Reload Window.</li><li>In the consumer repo, add an instance folder and <code>people.json</code> (<a href="./../configure">Configure</a>).</li><li>Sign in: <code>pnpm autodevelop login</code> (or <code>npx @devprecated/autodevelop login</code>). A lapsed organization stops with <code>Your billing has expired</code>.</li><li>An operator opens <strong>Connect GitHub</strong>, installs the Autodevelop GitHub App, and saves the Project (<a href="./../github">GitHub App</a>).</li><li>Developers use <code>pnpm autodevelop github token</code> when <code>gh</code> should act as the App. The CLI prints expiry, not the token.</li><li>Then:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fix</span></span></code></pre></div><p>Doctor exits non-zero on hard misses. <code>--fix</code> prints the next commands. Neither writes email nor invents a confirm token.</p><h2 id="what-must-work" tabindex="-1">What must work <a class="header-anchor" href="#what-must-work" aria-label="Permalink to &quot;What must work&quot;">​</a></h2><ul><li><code>node</code>, <code>pnpm</code></li><li>A paid organization and a stored CLI or plugin token</li><li>Autodevelop GitHub App installed on the customer org</li><li>Instance <code>config.json</code> with Project and field ids</li><li>Staging Firebase credentials for mail (never print the key)</li><li><code>.cursor/hooks.json</code></li></ul><p>Next: <a href="./create-tickets">create tickets</a>. If something fails: <a href="./when-something-breaks">when something breaks</a>.</p>`,8)])])}const k=i(n,[["render",s]]);export{u as __pageData,k as default};
